using System;using System.Linq;using System.Text.Json;using TownOfHost;using TownOfHost.Roles.Core;
class Program{static int passed;static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Setup(){OptionItem.Reset();Options.Reset();Logger.Errors.Clear();Logger.Warnings.Clear();RPC.Sent.Clear();CustomRoleManager.AllRolesInfo.Clear();
AuditDefs.Destroyer.RoleInfo=new(){RoleName=CustomRoles.Destroyer,ConfigId=39991,CustomRoleType=CustomRoleTypes.Impostor,Tab=TabGroup.ImpostorRoles,OptionSort=(0,8),OptionCreator=AuditDefs.Destroyer.Initialize};AuditDefs.Lethe.RoleInfo=new(){RoleName=CustomRoles.Lethe,ConfigId=39990,CustomRoleType=CustomRoleTypes.Crewmate,Tab=TabGroup.CrewmateRoles,OptionSort=(0,7),OptionCreator=AuditDefs.Lethe.Initialize};AuditDefs.ShrineMaiden.RoleInfo=new(){RoleName=CustomRoles.ShrineMaiden,ConfigId=40000,CustomRoleType=CustomRoleTypes.Crewmate,Tab=TabGroup.CrewmateRoles,OptionSort=(3,4),OptionCreator=AuditDefs.ShrineMaiden.Initialize};
foreach(var i in new[]{AuditDefs.Lethe.RoleInfo,AuditDefs.Destroyer.RoleInfo,AuditDefs.ShrineMaiden.RoleInfo})CustomRoleManager.AllRolesInfo.Add(i.RoleName,i);
var sorted=CustomRoleManager.AllRolesInfo.Values.OrderBy(i=>i.ConfigId);Options.CreateRoleOption(sorted,CustomRoleTypes.Impostor);Options.CreateRoleOption(sorted,CustomRoleTypes.Madmate);Options.CreateRoleOption(sorted,CustomRoleTypes.Crewmate);Options.CreateRoleOption(sorted,CustomRoleTypes.Neutral);}
static void Test(string n,Action a){Setup();a();passed++;Console.WriteLine("PASS "+n);}
static void Main(){
Test("all three roles attempt registration with zero spawn chance",()=>{Check(Options.CustomRoleSpawnChances.Count==3&&Options.CustomRoleCounts.Count==3,"role missing");Check(Options.CustomRoleSpawnChances.Values.All(o=>o.GetInt()==0),"default changed");});
Test("six conflicting IDs cause seven rejected registrations",()=>{Check(Logger.Errors.Count(s=>s.StartsWith("ID:"))==7,"rejection count");var ids=Logger.Errors.Where(s=>s.StartsWith("ID:")).Select(s=>int.Parse(s[3..s.IndexOf('が')])).Distinct().OrderBy(x=>x);Check(ids.SequenceEqual(new[]{39991,40000,40001,40002,40003,40004}),"IDs");});
Test("Destroyer wins 39991 and Lethe Maximum becomes orphan",()=>{Check(ReferenceEquals(OptionItem.FastOptions[39991],Options.CustomRoleSpawnChances[CustomRoles.Destroyer]),"first registered");Check(!OptionItem.AllOptions.Contains(Options.CustomRoleCounts[CustomRoles.Lethe]),"orphan registered");});
Test("Lethe task awakening wins 40000 and Shrine spawn becomes orphan",()=>{Check(ReferenceEquals(OptionItem.FastOptions[40000],AuditDefs.Lethe.OptNeedTasks),"first registered");Check(!OptionItem.AllOptions.Contains(Options.CustomRoleSpawnChances[CustomRoles.ShrineMaiden]),"Shrine visible");});
Test("Destroyer cooldown wins both Lethe task count and Shrine maximum",()=>{Check(ReferenceEquals(OptionItem.FastOptions[40001],AuditDefs.Destroyer.OptKillCooldown),"cooldown not first");Check(!OptionItem.AllOptions.Contains(AuditDefs.Lethe.OptRequiredTaskCount)&&!OptionItem.AllOptions.Contains(Options.CustomRoleCounts[CustomRoles.ShrineMaiden]),"duplicate objects registered");});
Test("Destroyer owns 40002 40003 40004 with independent Lethe references",()=>{Check(ReferenceEquals(OptionItem.FastOptions[40002],AuditDefs.Destroyer.OptShowKillFlash),"40002");Check(OptionItem.FastOptions[40003].Name=="Killdistance"&&ReferenceEquals(OptionItem.FastOptions[40004],AuditDefs.Destroyer.OptCrushTime),"40003 40004");Check(!OptionItem.AllOptions.Contains(AuditDefs.Lethe.OptHideUntilTasks)&&!OptionItem.AllOptions.Contains(AuditDefs.Lethe.OptGiveSealer)&&!OptionItem.AllOptions.Contains(AuditDefs.Lethe.OptGiveSecurer),"orphan flags");});
Test("orphan save is dropped and not restored on reload",()=>{AuditDefs.Lethe.OptRequiredTaskCount.SetValue(7,false,false);AuditDefs.Destroyer.OptKillCooldown.SetValue(12,false,false);var data=OptionSaver.Export();Check(data.PresetOptions[40001][0]==12,"saved wrong winner");var json=JsonSerializer.Serialize(data);Setup();OptionSaver.Import(JsonSerializer.Deserialize<OptionSaver.SerializableOptionsData>(json));Check(AuditDefs.Destroyer.OptKillCooldown.GetValue()==12&&AuditDefs.Lethe.OptRequiredTaskCount.GetValue()==0,"orphan restored");});
Test("legacy JSON keys affect only registered winner",()=>{var data=JsonSerializer.Deserialize<OptionSaver.SerializableOptionsData>(JsonSerializer.Serialize(OptionSaver.Export()));data.PresetOptions[40000][0]=0;AuditDefs.Lethe.OptNeedTasks.SetValue(1,false,false);OptionSaver.Import(data);Check(!AuditDefs.Lethe.OptNeedTasks.GetBool()&&Options.CustomRoleSpawnChances[CustomRoles.ShrineMaiden].GetInt()==0,"ambiguous load");});
Test("orphan single sync can target a different registered option",()=>{var orphan=Options.CustomRoleCounts[CustomRoles.Lethe];orphan.SetValue(6);var msg=RPC.Sent.Last();Check(msg.Id==39991&&msg.Value==6&&Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==0,"sender");OptionItem.FastOptions[msg.Id].SetValue(msg.Value,false,false);Check(Options.CustomRoleSpawnChances[CustomRoles.Destroyer].GetInt()==60&&orphan.GetInt()==7,"receiver mapped wrong");});
Test("full sync snapshot has only one value for every registered ID",()=>{var ids=OptionItem.AllOptions.Select(o=>o.Id).ToArray();Check(ids.Length==ids.Distinct().Count(),"duplicate in all list");Check(!OptionItem.AllOptions.Contains(Options.CustomRoleCounts[CustomRoles.Lethe]),"orphan included");});
Test("all sixteen presets drop orphan values independently",()=>{for(int p=0;p<16;p++){OptionItem.CurrentPreset=p;AuditDefs.Lethe.OptRequiredTaskCount.SetValue(p%10,false,false);AuditDefs.Destroyer.OptKillCooldown.SetValue(p,false,false);}var data=OptionSaver.Export();Check(data.PresetOptions[40001].SequenceEqual(Enumerable.Range(0,16)),"winner snapshots");Setup();OptionSaver.Import(data);Check(AuditDefs.Lethe.OptRequiredTaskCount.AllValues.All(v=>v==0),"orphan persists");});
Console.WriteLine($"RESULT {passed} passed, 0 failed");}}
